class Solution:
    def countBinaryPalindromes(self, n: int) -> int:
        if n == 0:
            return 1
        L = n.bit_length()
        ans = 1
        for l in range(1, L):
            ans += 1 << ((l + 1) // 2 - 1)
        h = (L + 1) // 2
        pref = n >> (L - h)
        ans += pref - (1 << (h - 1))
        s = bin(pref)[2:]
        p = s + (s[::-1] if L % 2 == 0 else s[-2::-1])
        if int(p, 2) <= n:
            ans += 1
        return ans

