class Solution {
public:
    int countBinaryPalindromes(long long n) {
        if (n == 0) return 1;
        int L = 64 - __builtin_clzll(n);
        long long ans = 1;
        for (int l = 1; l < L; l++) ans += 1LL << ((l + 1) / 2 - 1);
        int h = (L + 1) / 2;
        long long pref = n >> (L - h);
        ans += pref - (1LL << (h - 1));
        long long p = pref;
        long long mirror = pref >> (L % 2 ? 1 : 0);
        for (int b = 0; b < h - (L % 2 ? 1 : 0); b++)
            if ((mirror >> b) & 1) p |= 1LL << (h + b);
        if (p <= n) ans += 1;
        return (int)ans;
    }
};

