class Solution {
    public int countBinaryPalindromes(long n) {
        if (n == 0) return 1;
        int L = 64 - Long.numberOfLeadingZeros(n);
        long ans = 1;
        for (int l = 1; l < L; l++) ans += 1L << ((l + 1) / 2 - 1);
        int h = (L + 1) / 2;
        long pref = n >> (L - h);
        ans += pref - (1L << (h - 1));
        long p = pref;
        long mirror = pref >> (L % 2 == 0 ? 0 : 1);
        int mb = h - (L % 2 == 0 ? 0 : 1);
        for (int b = 0; b < mb; b++)
            if ((mirror >> b & 1) == 1) p |= 1L << (h + b);
        if (p <= n) ans += 1;
        return (int) ans;
    }
}

