var countBinaryPalindromes = function(n) {
    if (n === 0) return 1;
    const N = BigInt(n);
    let L = N.toString(2).length;
    let ans = 1n;
    for (let l = 1; l < L; l++) ans += 1n << BigInt((l + 1) / 2 - 1);
    const h = (L + 1) >> 1;
    const pref = N >> BigInt(L - h);
    ans += pref - (1n << BigInt(h - 1));
    const s = pref.toString(2);
    const pStr = s + (L % 2 === 0 ? s.split('').reverse().join('') : s.slice(0, -1).split('').reverse().join(''));
    if (BigInt('0b' + pStr) <= N) ans += 1n;
    return Number(ans);
};
